rss.channel:
  {{ feed.title }}
  {{ feed.home }}

  {{ feed.description }}
  {{ feed.language }}
  {{ site.built_at | rfc822 }}
  {{ site.name }} newsroom
{% for a in articles %}


    {{ a.headline }}
    {{ site.url }}/{{ feed.prefix }}articles/{{ a.slug }}/
    {{ site.url }}/{{ feed.prefix }}articles/{{ a.slug }}/
    {{ a.published_at | rfc822 }}
    {{ a.dek }}
    {% for t in a.tags %}{{ t }}
    {% endfor %}
    {% if a.image %}


      {{ a.image.credit.line() }}
      {{ a.image.alt }}

    {% endif %}
    {% if a.image %}<p><img src="{{ site.url }}/images/{{ a.image.path.split('/')[-1] }}" alt="{{ a.image.alt }}"><br><small>{{ a.image.credit.line() }}</small></p>{% endif %}{{ a.body_markdown | markdown }}<p>{{ 'स्रोतहरू' if feed.language == 'ne' else 'Sources' }}: {% for s in a.sources %}<a href="{{ s.url }}">{{ s.name }}</a>{% if not loop.last %}, {% endif %}{% endfor %}</p>

{% endfor %}
